/* ===== Tokens ===== */
:root {
  --bg: #f5f6f9;
  --surface: #ffffff;
  --surface-2: #fafbfd;
  --ink: #1a212b;
  --ink-2: #4d5766;
  --ink-3: #66707f;
  --line: #dfe4ec;
  --line-soft: #e9edf3;

  --accent: #4338ca;
  --accent-ink: #3730a3;
  --accent-soft: #eef2ff;
  --accent-line: #c7d2fe;

  --danger: #b42318;
  --danger-ink: #912018;
  --danger-soft: #fef3f2;
  --danger-line: #f4c7c3;

  --warn-bg: #fffaeb;
  --warn-line: #fedf89;
  --warn-ink: #93540a;

  --ok: #067647;
  --ok-soft: #ecfdf3;
  --ok-line: #abefc6;

  --radius: 14px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(16, 24, 32, .05), 0 4px 16px rgba(16, 24, 32, .06);
  --shadow-deep: 0 8px 40px rgba(16, 24, 32, .22);
  --font: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: "Cascadia Code", Consolas, "SF Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
