  font-size: 14px; box-shadow: var(--shadow-deep); z-index: 80;
}

@media (max-width: 860px) {
  .app { padding: 28px 18px 60px; }
  .runbook-header { flex-direction: column; gap: 18px; }
  .rh-right { width: 100%; }
  .c-stats { grid-template-columns: repeat(2, 1fr); }
  .step-body { padding-left: 20px; }
