.step-marker svg { width: 16px; height: 16px; }

.step-main { flex: 1 1 auto; min-width: 0; }
.step-title-line { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.step-title { font-weight: 650; font-size: 16px; }
.step.is-locked .step-title { color: var(--ink-2); font-weight: 550; }
.step-summary { margin: 2px 0 0; font-size: 13.5px; color: var(--ink-3); }

.step-side { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
.badge {
  font-size: 11px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase;
  padding: 3px 9px; border-radius: 999px; white-space: nowrap;
}
.badge-irrev { background: var(--warn-bg); color: var(--warn-ink); border: 1px solid var(--warn-line); }
.badge-check { background: var(--surface-2); color: var(--ink-3); border: 1px solid var(--line); }
.badge-done { background: var(--ok-soft); color: var(--ok); border: 1px solid var(--ok-line); }
.badge-rolled { background: var(--danger-soft); color: var(--danger); border: 1px solid var(--danger-line); }
.badge-upnext { background: var(--accent-soft); color: var(--accent-ink); border: 1px solid var(--accent-line); }
.step-chev { color: var(--ink-3); transition: transform .2s ease; }
.step.is-open .step-chev { transform: rotate(180deg); }

