1	/* Runbook walker — strict-order execution of one high-consequence workflow.
2	   Irreversible steps pass a typed confirmation gate that previews the rollback plan;
3	   executed irreversible steps keep an inline recovery path. All data is inlined
4	   (data.js), so the first paint is the complete, usable screen. */
5	(function () {
6	  "use strict";
7	
8	  var RB = window.RUNBOOK;
9	
10	  /* ---------- Flatten phases → ordered steps with prerequisites ---------- */
11	  var PHASES = RB.phases.map(function (p, pi) {
12	    return {
13	      id: p.id, num: pi + 1, title: p.title, goal: p.goal,
14	      steps: p.steps
15	    };
16	  });
17	  var STEPS = [];
18	  PHASES.forEach(function (p) {
19	    p.steps.forEach(function (s, si) {
