50	  /* ---------- Helpers ---------- */
51	  function now() { return new Date().toLocaleTimeString("en-GB", { hour12: false }); }
52	  function log(type, text) { store.log.push({ t: now(), type: type, text: text }); }
53	  function isDone(id) { return !!store.done[id]; }
54	  function isUnlocked(s) {
