403	    if (!s || !isDone(id) || s.reversible) return;
404	    if (!rollbackAvailable(s)) return;
405	    if (store.rollbackArmed !== id) {
406	      store.rollbackArmed = id;
407	      render();
408	      return;
409	    }
410	    store.rollbackArmed = null;
411	    delete store.done[id];
412	    store.rolledBack[id] = true;
413	    log("rollback", "Rolled back \"" + s.title + "\" via: " + s.rollback.title + " (" + s.rollback.rto + "). Step re-armed for re-execution.");
