439	  /* ---------- Events (delegated) ---------- */
440	  document.addEventListener("click", function (ev) {
441	    var el = ev.target.closest("[data-action]");
442	    if (!el) {
443	      if (store.gateStepId && ev.target === document.getElementById("gate-scrim")) closeGate();
444	      return;
445	    }
446	    var a = el.dataset.action, id = el.dataset.step;
447	    switch (a) {
448	      case "toggle-step": toggleStep(id); break;
449	      case "complete": completeStep(id); break;
450	      case "open-gate": openGate(id); break;
451	      case "rollback": rollback(id); break;
452	      case "close-gate": closeGate(); break;
