/* ===== Tokens ===== */
:root {
  --bg: #f5f6f9;
  --surface: #ffffff;
  --surface-2: #fafbfd;
  --ink: #1a212b;
  --ink-2: #4d5766;
  --ink-3: #66707f;
  --line: #dfe4ec;
  --line-soft: #e9edf3;

  --accent: #4338ca;
  --accent-ink: #3730a3;
  --accent-soft: #eef2ff;
  --accent-line: #c7d2fe;

  --danger: #b42318;
  --danger-ink: #912018;
  --danger-soft: #fef3f2;
  --danger-line: #f4c7c3;

  --warn-bg: #fffaeb;
  --warn-line: #fedf89;
  --warn-ink: #93540a;

  --ok: #067647;
  --ok-soft: #ecfdf3;
  --ok-line: #abefc6;

  --radius: 14px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(16, 24, 32, .05), 0 4px 16px rgba(16, 24, 32, .06);
  --shadow-deep: 0 8px 40px rgba(16, 24, 32, .22);
  --font: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: "Cascadia Code", Consolas, "SF Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.app { max-width: 940px; margin: 0 auto; padding: 44px 36px 80px; }

/* ===== Header ===== */
.runbook-header {
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 32px; padding-bottom: 28px; border-bottom: 1px solid var(--line);
}
.rh-eyebrow {
  margin: 0 0 6px; font-size: 12.5px; font-weight: 700; letter-spacing: .12em;
  text-transform: uppercase; color: var(--accent-ink);
}
.rh-title { margin: 0 0 10px; font-size: 30px; line-height: 1.2; letter-spacing: -.01em; }
.rh-meta { margin: 0; color: var(--ink-2); font-size: 14.5px; }
.rh-meta span { display: inline-block; margin-right: 18px; }

.rh-right { flex: 0 0 auto; width: 264px; display: flex; flex-direction: column; gap: 10px; margin-top: 4px; }
.rh-status-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.status-pill {
  font-size: 12.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: 5px 12px; border-radius: 999px; border: 1px solid var(--line); background: var(--surface); color: var(--ink-2);
  white-space: nowrap;
}
.status-pill[data-state="in-progress"] { background: var(--accent-soft); border-color: var(--accent-line); color: var(--accent-ink); }
.status-pill[data-state="complete"] { background: var(--ok-soft); border-color: var(--ok-line); color: var(--ok); }
.progress-label { font-size: 13.5px; color: var(--ink-2); font-variant-numeric: tabular-nums; }

.meter { height: 8px; border-radius: 999px; background: var(--line-soft); overflow: hidden; }
.meter-fill {
  height: 100%; width: 0%; border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), #6d64e8);
  transition: width .35s ease;
}
.rh-actions { display: flex; gap: 8px; justify-content: flex-end; }

/* ===== Buttons ===== */
.btn {
  font: inherit; font-size: 14.5px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 16px; border-radius: var(--radius-s);
  border: 1px solid var(--line); background: var(--surface); color: var(--ink);
  cursor: pointer; transition: background .15s ease, border-color .15s ease, box-shadow .15s ease;
}
.btn:hover:not(:disabled) { background: var(--surface-2); border-color: #cdd4df; }
.btn-primary { background: #3730a3; border-color: #3730a3; color: #fff; }
.btn-primary:hover:not(:disabled) { background: #312a94; border-color: #312a94; }
.btn-danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { background: var(--danger-ink); border-color: var(--danger-ink); }
.btn-danger-ghost { background: transparent; border-color: var(--danger-line); color: var(--danger); }
.btn-danger-ghost:hover:not(:disabled) { background: var(--danger-soft); }
.btn-ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn-ghost:hover:not(:disabled) { background: rgba(16, 24, 32, .06); border-color: transparent; }
.btn-small { font-size: 13px; padding: 6px 11px; }
.btn-large { font-size: 15.5px; padding: 11px 22px; }
/* Disabled: solid, no opacity (keeps text contrast measurable and AA-safe). */
.btn:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; cursor: not-allowed; }
.btn-primary:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }
.btn-danger:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }
.btn-danger-ghost:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }

.ic { width: 16px; height: 16px; flex: 0 0 auto; }

/* ===== Completion banner ===== */
.completion {
  margin-top: 32px; padding: 28px 32px;
  background: linear-gradient(135deg, var(--ok-soft), #f2fbf6 60%, var(--accent-soft));
  border: 1px solid var(--ok-line); border-radius: var(--radius); box-shadow: var(--shadow);
}
.completion h2 { margin: 0 0 6px; font-size: 22px; display: flex; align-items: center; gap: 12px; }
.completion h2 svg { width: 28px; height: 28px; color: var(--ok); }
.completion .c-sub { margin: 0 0 20px; color: var(--ink-2); }
.c-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 20px; }
.c-stat {
  background: rgba(255,255,255,.75); border: 1px solid var(--line-soft);
  border-radius: var(--radius-s); padding: 12px 16px;
}
.c-stat b { display: block; font-size: 22px; font-variant-numeric: tabular-nums; }
.c-stat span { font-size: 12.5px; color: var(--ink-2); letter-spacing: .02em; text-transform: uppercase; font-weight: 600; }
.c-phases { margin: 0; padding: 0; list-style: none; border-top: 1px dashed var(--line); padding-top: 16px; }
.c-phases li { margin: 6px 0; font-size: 14px; color: var(--ink-2); }
.c-phases b { color: var(--ink); }

/* ===== Ladder ===== */
.ladder { margin-top: 8px; }
.phase { margin-top: 40px; }
.phase-head { display: flex; align-items: baseline; gap: 14px; margin-bottom: 8px; }
.phase-num {
  flex: 0 0 auto; width: 34px; height: 34px; border-radius: 999px;
  background: var(--ink); color: #fff; font-weight: 700; font-size: 15px;
  display: inline-flex; align-items: center; justify-content: center; align-self: center;
}
.phase.is-complete .phase-num { background: var(--ok); }
.phase-title { margin: 0; font-size: 20px; }
.phase-goal { margin: 0 0 18px 48px; color: var(--ink-3); font-size: 14.5px; }
.phase-count { margin-left: auto; font-size: 13px; color: var(--ink-3); font-variant-numeric: tabular-nums; white-space: nowrap; align-self: center; }

/* ===== Step ===== */
.step {
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); margin-bottom: 12px; box-shadow: var(--shadow);
  transition: border-color .2s ease, box-shadow .2s ease, opacity .2s ease;
}
.step.is-locked { background: var(--surface-2); }
.step.is-locked .step-title { color: var(--ink-2); }
.step.is-locked .step-summary { color: var(--ink-3); }
.step.is-current { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft), var(--shadow); }
.step.is-done:not(.is-current) { border-color: var(--ok-line); }
.step.is-done .step-marker { color: var(--ok); }

.step-row {
  width: 100%; display: flex; align-items: center; gap: 14px; text-align: left;
  background: none; border: 0; padding: 16px 20px; cursor: pointer; font: inherit; color: inherit;
  border-radius: var(--radius);
}
.step-row:hover { background: var(--surface-2); }
.step.is-locked .step-row { cursor: default; }
.step.is-locked .step-row:hover { background: none; }

.step-marker {
  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 2px solid var(--line); color: var(--ink-3); background: var(--surface);
}
.step.is-current .step-marker { border-color: var(--accent); color: var(--accent); }
.step-marker svg { width: 16px; height: 16px; }

.step-main { flex: 1 1 auto; min-width: 0; }
.step-title-line { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.step-title { font-weight: 650; font-size: 16px; }
.step.is-locked .step-title { color: var(--ink-2); font-weight: 550; }
.step-summary { margin: 2px 0 0; font-size: 13.5px; color: var(--ink-3); }

.step-side { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
.badge {
  font-size: 11px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase;
  padding: 3px 9px; border-radius: 999px; white-space: nowrap;
}
.badge-irrev { background: var(--warn-bg); color: var(--warn-ink); border: 1px solid var(--warn-line); }
.badge-check { background: var(--surface-2); color: var(--ink-3); border: 1px solid var(--line); }
.badge-done { background: var(--ok-soft); color: var(--ok); border: 1px solid var(--ok-line); }
.badge-rolled { background: var(--danger-soft); color: var(--danger); border: 1px solid var(--danger-line); }
.badge-upnext { background: var(--accent-soft); color: var(--accent-ink); border: 1px solid var(--accent-line); }
.step-chev { color: var(--ink-3); transition: transform .2s ease; }
.step.is-open .step-chev { transform: rotate(180deg); }

/* Step body */
.step-body { padding: 2px 20px 20px 64px; }
.step-detail { margin: 0 0 14px; padding: 0; list-style: none; }
.step-detail li { position: relative; padding-left: 20px; margin: 7px 0; font-size: 14.5px; color: var(--ink-2); }
.step-detail li::before {
  content: ""; position: absolute; left: 2px; top: .62em;
  width: 7px; height: 7px; border-radius: 2px; background: var(--accent-line);
}
.step-detail code {
  font-family: var(--mono); font-size: 12.5px; background: var(--surface-2);
  border: 1px solid var(--line-soft); border-radius: 5px; padding: 1px 5px;
}

.step-meta { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-bottom: 16px; font-size: 13px; color: var(--ink-3); }
.step-meta b { color: var(--ink-2); font-weight: 600; }

.checks { margin: 0 0 16px; padding: 14px 16px; background: var(--surface-2); border: 1px solid var(--line-soft); border-radius: var(--radius-s); }
.checks-title { margin: 0 0 8px; font-size: 13px; font-weight: 700; color: var(--ink-2); text-transform: uppercase; letter-spacing: .07em; }
.check { display: flex; gap: 10px; align-items: flex-start; margin: 6px 0; font-size: 14.5px; cursor: pointer; }
.check input { width: 24px; height: 24px; margin: 0; flex: 0 0 auto; accent-color: #3730a3; cursor: pointer; }
.check input:disabled { cursor: not-allowed; }

.step-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.step-hint { font-size: 13px; color: var(--ink-3); }
.step-hint.is-error { color: var(--danger); font-weight: 600; }
.step-outcome {
  margin: 0 0 14px; padding: 10px 14px; border-radius: var(--radius-s);
  background: var(--ok-soft); border: 1px solid var(--ok-line);
  color: var(--ok); font-size: 14px; font-weight: 600;
}
.rb-note {
  margin: 12px 0 0; font-size: 13px; color: var(--ink-3);
  padding: 10px 14px; background: var(--surface-2); border: 1px dashed var(--line); border-radius: var(--radius-s);
}

/* ===== Footer ===== */
.app-foot { margin-top: 56px; padding-top: 20px; border-top: 1px solid var(--line); }
.app-foot p { margin: 0; font-size: 13px; color: var(--ink-3); }

/* ===== Confirm gate (modal) ===== */
.scrim {
  position: fixed; inset: 0; background: rgba(13, 18, 26, .58);
  display: flex; align-items: flex-start; justify-content: center;
  padding: 7vh 24px 24px; overflow-y: auto; z-index: 60;
}
.gate {
  width: 620px; max-width: 100%; background: var(--surface);
  border-radius: 18px; box-shadow: var(--shadow-deep); padding: 30px 34px 28px;
}
.gate-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--danger); background: var(--danger-soft); border: 1px solid var(--danger-line);
  padding: 4px 12px; border-radius: 999px; margin: 0 0 14px;
}
.gate-eyebrow svg { width: 14px; height: 14px; }
.gate h2 { margin: 0 0 8px; font-size: 22px; }
.gate-consequence {
  margin: 0 0 18px; font-size: 14.5px; color: var(--ink-2);
  padding: 12px 16px; background: var(--danger-soft); border: 1px solid var(--danger-line);
  border-radius: var(--radius-s);
}
.rb-card {
  margin-bottom: 18px; padding: 16px 18px; border-radius: var(--radius-s);
  background: var(--warn-bg); border: 1px solid var(--warn-line);
}
.rb-card h3 { margin: 0 0 4px; font-size: 13px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--warn-ink); }
.rb-card .rb-title { margin: 0 0 10px; font-size: 15.5px; font-weight: 650; color: var(--ink); }
.rb-card ol { margin: 0 0 10px; padding-left: 20px; }
.rb-card li { margin: 4px 0; font-size: 14px; color: var(--ink-2); }
.rb-card .rb-meta { display: flex; gap: 16px; font-size: 13px; color: var(--warn-ink); font-weight: 600; }

.gate-checks { margin: 0 0 16px; }
.gate-phrase label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 8px; }
.gate-phrase label code {
  font-family: var(--mono); background: var(--surface-2); border: 1px solid var(--line);
  padding: 1px 7px; border-radius: 5px; font-size: 13px; letter-spacing: .04em;
}
.gate-phrase input {
  width: 100%; font-family: var(--mono); font-size: 15px; letter-spacing: .06em;
  padding: 11px 14px; border-radius: var(--radius-s); border: 1.5px solid var(--line);
  color: var(--ink); background: var(--surface);
}
.gate-phrase input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px var(--accent-soft); }
.gate-phrase .phrase-error { margin: 7px 0 0; font-size: 13px; color: var(--danger); font-weight: 600; min-height: 1.2em; }

.gate-actions { display: flex; justify-content: flex-end; gap: 12px; margin-top: 22px; }

/* ===== Activity log drawer ===== */
.log-drawer {
  position: fixed; top: 0; right: 0; bottom: 0; width: 400px; max-width: 92vw;
  background: var(--surface); border-left: 1px solid var(--line); box-shadow: -12px 0 40px rgba(16,24,32,.12);
  transform: translateX(102%); visibility: hidden;
  transition: transform .25s ease, visibility 0s linear .25s; z-index: 50;
  display: flex; flex-direction: column; padding: 22px 24px;
}
.log-drawer.open { transform: translateX(0); visibility: visible; transition: transform .25s ease; }
.log-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; margin-bottom: 14px; }
.log-head h2 { margin: 0; font-size: 17px; flex: 1 1 auto; }
.log-sub { flex-basis: 100%; margin: 0 0 2px; font-size: 12.5px; color: var(--ink-3); }
.log-list { flex: 1 1 auto; overflow-y: auto; margin: 0; padding: 0; list-style: none; }
.log-list li { display: flex; gap: 10px; padding: 10px 2px; border-bottom: 1px solid var(--line-soft); font-size: 13.5px; align-items: baseline; }
.log-time { flex: 0 0 auto; font-variant-numeric: tabular-nums; color: var(--ink-3); font-size: 12px; }
.log-chip {
  flex: 0 0 auto; font-size: 10.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line); color: var(--ink-3); background: var(--surface-2);
}
.log-chip-executed { background: var(--accent-soft); color: var(--accent-ink); border-color: var(--accent-line); }
.log-chip-confirmed { background: #f5f0ff; color: #6941c6; border-color: #d6bbfb; }
.log-chip-rollback { background: var(--warn-bg); color: var(--warn-ink); border-color: var(--warn-line); }
.log-chip-reset { background: var(--danger-soft); color: var(--danger); border-color: var(--danger-line); }
.log-text { color: var(--ink-2); }
.log-empty { color: var(--ink-3); font-size: 14px; }

/* ===== Toast ===== */
#toast {
  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%);
  background: var(--ink); color: #fff; padding: 11px 20px; border-radius: 10px;
  font-size: 14px; box-shadow: var(--shadow-deep); z-index: 80;
}

@media (max-width: 860px) {
  .app { padding: 28px 18px 60px; }
  .runbook-header { flex-direction: column; gap: 18px; }
  .rh-right { width: 100%; }
  .c-stats { grid-template-columns: repeat(2, 1fr); }
  .step-body { padding-left: 20px; }
}

/* Zero-dependency CDP driver: replays the full runbook user journey in headless
   Chrome with real input events, asserts app behavior, and saves screenshot
   evidence to screenshots/. Run: node scripts/drive.cjs */
"use strict";
const fs = require("fs");
const path = require("path");
const { spawn } = require("child_process");

const CHROME = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const ROOT = "E:\\codex-prj\\ab-worktrees\\pi-matrix-m5p1\\s4-e1";
const SHOTS = path.join(ROOT, "screenshots");
const PORT = 9333;
const APP_URL = "file:///E:/codex-prj/ab-worktrees/pi-matrix-m5p1/s4-e1/index.html";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const results = [];
const consoleErrs = [];
function check(label, cond, detail) {
  results.push({ label, pass: !!cond, detail: detail || "" });
  console.log((cond ? "PASS  " : "FAIL  ") + label + (detail ? "  [" + detail + "]" : ""));
}
async function expectText(label, actual, wanted) {
  check(label, actual === wanted || (wanted instanceof RegExp && wanted.test(actual)), JSON.stringify(actual));
}

async function main() {
  fs.mkdirSync(SHOTS, { recursive: true });
  const profile = path.join(ROOT, ".chrome-test-profile");
  const chrome = spawn(CHROME, [
    "--headless=new", "--disable-gpu", "--remote-debugging-port=" + PORT,
    "--user-data-dir=" + profile, "--no-first-run", "--window-size=1440,900",
    "--hide-scrollbars", "about:blank"
  ], { stdio: "ignore" });

  let targets = [];
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch("http://127.0.0.1:" + PORT + "/json/list");
      targets = await res.json();
      if (targets.some((t) => t.type === "page")) break;
    } catch (_) {}
    await sleep(200);
  }
  const page = targets.find((t) => t.type === "page");
  if (!page) throw new Error("no devtools page target");
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  let mid = 0;
  const pending = new Map();
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
    if (msg.method === "Runtime.consoleAPICalled" && msg.params.type === "error")
      consoleErrs.push(msg.params.args.map((a) => a.value || a.description || "").join(" "));
    if (msg.method === "Runtime.exceptionThrown") {
      const d = msg.params.exceptionDetails;
      consoleErrs.push((d.text || "") + " " + ((d.exception && d.exception.description) || ""));
    }
  };
  function send(method, params) {
    return new Promise((resolve, reject) => {
      const id = ++mid;
      pending.set(id, (m) => (m.error ? reject(new Error(method + ": " + JSON.stringify(m.error))) : resolve(m.result)));
      ws.send(JSON.stringify({ id, method, params: params || {} }));
    });
  }
  async function evaljs(expr) {
    const r = await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error("eval failed: " + JSON.stringify((r.exceptionDetails.exception || {}).description || r.exceptionDetails.text));
    return r.result.value;
  }
  async function shot(name, fullPage) {
    const r = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: !!fullPage });
    fs.writeFileSync(path.join(SHOTS, name), Buffer.from(r.data, "base64"));
  }
  const sel = (s) => "document.querySelector(" + JSON.stringify(s) + ")";
  async function textOf(s) { return evaljs("((" + sel(s) + ")||{textContent:'(missing)'}).textContent.trim()"); }
  async function count(s) { return evaljs("document.querySelectorAll(" + JSON.stringify(s) + ").length"); }
  async function exists(s) { return evaljs("!!" + sel(s)); }
  async function clickAt(s) {
    const c = await evaljs("(() => { const el = " + sel(s) + "; if (!el) return null; el.scrollIntoView({block:'center'}); const r = el.getBoundingClientRect(); return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) }; })()");
    if (!c) throw new Error("element not found: " + s);
    await send("Input.dispatchMouseEvent", { type: "mousePressed", x: c.x, y: c.y, button: "left", clickCount: 1 });
    await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: c.x, y: c.y, button: "left", clickCount: 1 });
    await sleep(90);
  }
  async function typeInto(s, str) {
    await evaljs("(() => { const el = " + sel(s) + "; el.focus(); el.value = ''; })()");
    for (const ch of str) {
      await send("Input.dispatchKeyEvent", { type: "keyDown", key: ch, text: ch });
      await send("Input.dispatchKeyEvent", { type: "keyUp", key: ch });
    }
    await sleep(50);
    const v = await evaljs(sel(s) + ".value");
    if (v !== str) { // fallback: direct set + event (still exercises the app handler)
      await evaljs("(() => { const el = " + sel(s) + "; el.value = " + JSON.stringify(str) + "; el.dispatchEvent(new Event('input', { bubbles: true })); })()");
    }
    await sleep(50);
  }
  async function tabTimes(n) {
    for (let i = 0; i < n; i++) {
      await send("Input.dispatchKeyEvent", { type: "keyDown", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9 });
      await send("Input.dispatchKeyEvent", { type: "keyUp", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9 });
      await sleep(60);
    }
  }
  function activeDesc() {
    return evaljs("(() => { const a = document.activeElement; if (!a) return '(none)'; return a.tagName.toLowerCase() + (a.id ? '#' + a.id : '') + (a.dataset && a.dataset.action ? '[' + a.dataset.action + ']' : '') + (a.dataset && a.dataset.step ? ':' + a.dataset.step : '') + (a.dataset && a.dataset.check ? ':' + a.dataset.check : ''); })()");
  }
  async function gateFlow(stepId, phrase) {
    await clickAt("button[data-action='open-gate'][data-step='" + stepId + "']");
    await sleep(120);
    await typeInto("#gate-phrase-input", phrase);
    await clickAt("input[data-gate-check='0']");
    await clickAt("input[data-gate-check='1']");
    const disabled = await evaljs("(document.querySelector(\"#gate [data-action='gate-execute']\")||{}).disabled");
    if (disabled) throw new Error("gate execute stayed disabled for " + stepId);
    await clickAt("#gate [data-action='gate-execute']");
    await sleep(120);
  }
  async function completeSimple(stepId, checkpoints) {
    for (let i = 0; i < (checkpoints || 0); i++) await clickAt("input[data-check='" + stepId + ":" + i + "']");
    await clickAt("button[data-action='complete'][data-step='" + stepId + "']");
    await sleep(90);
  }

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
  await send("Page.navigate", { url: APP_URL });
  await sleep(1200);

  /* Stage 1 — first paint */
  check("S1: title", (await evaljs("document.title")) === "Ledger v2 Cutover — Runbook");
  await expectText("S1: progress label 0 of 10", await textOf("#progress-label"), "0 of 10 steps");
  await expectText("S1: status pill", await textOf("#status-pill"), "Not started");
  check("S1: 10 steps rendered", (await count("article.step")) === 10);
  check("S1: 4 phases rendered", (await count("section.phase")) === 4);
  check("S1: step 1 expanded with 2 checkpoints", (await count(".step[data-step-id='S1'] .check input")) === 2);
  check("S1: step 1 complete button enabled", (await evaljs("!(" + sel("button[data-action='complete'][data-step='S1']") + ").disabled")));
  check("S1: step 2 locked", (await evaljs(sel(".step[data-step-id='S2']") + ".classList.contains('is-locked')")));
  check("S1: no loading state text", !(await evaljs("document.body.textContent.toLowerCase().includes('loading')")));
  await shot("01-first-paint.png");
  await shot("01b-first-paint-full.png", true);

  /* Stage 2 — keyboard */
  const foc = [];
  for (let i = 0; i < 4; i++) { await tabTimes(1); foc.push(await activeDesc()); }
  check("S2: tab order starts at Activity log", foc[0] === "button#log-toggle", foc.join(" -> "));
  check("S2: 4th stop is step-1 checkpoint", foc[3] === "input[data-check]:S1:0", foc[3]);
  check("S2: focus visible (focus-visible matches)", await evaljs("document.activeElement.matches(':focus-visible')"));
  await shot("02-keyboard-focus.png");

  /* Stage 3 — complete reversible steps 1..4 */
  await completeSimple("S1", 2);
  await completeSimple("S2", 2);
  await completeSimple("S3", 0);
  await completeSimple("S4", 0);
  await expectText("S3: progress 4 of 10", await textOf("#progress-label"), "4 of 10 steps");
  await expectText("S3: status in progress", await textOf("#status-pill"), "In progress");
  check("S3: step 5 is current", await evaljs(sel(".step[data-step-id='S5']") + ".classList.contains('is-current')"));
  await expectText("S3: irreversible badge", await textOf(".step[data-step-id='S5'] .badge-irrev"), "Irreversible");
  check("S3: gate button enabled", await evaljs("!(" + sel("button[data-action='open-gate'][data-step='S5']") + ").disabled"));
  await shot("03-progress-midway.png");

  /* Stage 4 — confirm gate for step 5 */
  await clickAt("button[data-action='open-gate'][data-step='S5']");
  await sleep(120);
  check("S4: gate open", await exists("#gate .gate-eyebrow"));
  await expectText("S4: gate eyebrow", await textOf("#gate .gate-eyebrow"), "Irreversible — point of no return");
  check("S4: consequence states irreversibility", (await textOf("#gate .gate-consequence")).includes("v1 stops accepting writes"));
  check("S4: rollback plan card present", (await textOf("#gate .rb-card h3")).includes("Rollback plan — your recovery path"));
  check("S4: rollback rto shown", (await textOf("#gate .rb-card")).includes("≤ 10 min"));
  check("S4: two acknowledgement checkboxes", (await count("#gate input[data-gate-check]")) === 2);
  check("S4: typed phrase prompt", (await textOf("#gate .gate-phrase label")).includes("LEDGER V2"));
  check("S4: execute disabled initially", await evaljs("(" + sel("#gate [data-action='gate-execute']") + ").disabled"));
  await shot("04-confirm-gate.png");
  await typeInto("#gate-phrase-input", "WRONG");
  check("S4: execute still disabled on wrong phrase", await evaljs("(" + sel("#gate [data-action='gate-execute']") + ").disabled"));
  check("S4: inline phrase error shown", (await textOf("#gate-phrase-error")).includes("does not match"));
  await shot("05-gate-error.png");
  await typeInto("#gate-phrase-input", "ledger v2");
  check("S4: phrase match is case-insensitive (value 'ledger v2')", (await evaljs(sel("#gate-phrase-input") + ".value")) === "ledger v2");
  check("S4: error hint cleared", (await textOf("#gate-phrase-error")) === "");
  await clickAt("input[data-gate-check='0']");
  await clickAt("input[data-gate-check='1']");
  check("S4: execute enabled after checks+phrase", await evaljs("!(" + sel("#gate [data-action='gate-execute']") + ").disabled"));
  await clickAt("#gate [data-action='gate-execute']");
  await sleep(150);
  check("S4: gate closed after execute", await evaljs("(" + sel("#gate-scrim") + ").hidden"));
  check("S4: step 5 done", await evaljs(sel(".step[data-step-id='S5']") + ".classList.contains('is-done')"));
  check("S4: rollback button available on step 5", await exists("button[data-action='rollback'][data-step='S5']:not([disabled])"));
  await shot("06-after-cutover.png");

  /* Stage 5 — rollback path */
  await clickAt("button[data-action='rollback'][data-step='S5']");
  await sleep(100);
  await expectText("S5: rollback arms (two-click)", await textOf("button[data-action='rollback'][data-step='S5']"), "Confirm rollback");
  await shot("07-rollback-armed.png");
  await clickAt("button[data-action='rollback'][data-step='S5']");
  await sleep(120);
  await expectText("S5: progress back to 4 of 10", await textOf("#progress-label"), "4 of 10 steps");
  check("S5: rolled-back badge shown", await exists(".step[data-step-id='S5'] .badge-rolled"));
  check("S5: rollback logged", (await evaljs("document.body.textContent")).includes("Rolled back \\\"Cut over write traffic"));
  await shot("07b-rollback-done.png");

  /* Stage 6 — re-execute 5, then 6..10 to completion */
  await gateFlow("S5", "ledger v2");
  check("S6a: re-executed step 5 shows Done (not Rolled back)", await exists(".step[data-step-id='S5'] .badge-done"));
  await gateFlow("S6", "revoke v1");
  await completeSimple("S7", 3);
  await gateFlow("S8", "retire v1");
  await completeSimple("S9", 0);
  await completeSimple("S10", 0);
  await sleep(150);
  check("S6: completion banner visible", await evaljs("!(" + sel("#completion") + ").hidden"));
  check("S6: banner says zero missteps", (await textOf("#completion h2")).includes("zero missteps"));
  check("S6: stats 10/10 steps", (await textOf("#completion")).includes("10/10"));
  check("S6: stats 3/3 gates confirmed", (await textOf("#completion")).includes("3/3"));
  check("S6: rollbacks exercised = 1", (await textOf("#completion")).includes(">1<") || (await evaljs("document.querySelectorAll('.c-stat b')[2].textContent")) === "1");
  check("S6: per-phase roll-up lists all steps", (await count("#completion .c-phases li")) === 14);
  await shot("08-completion.png");

  /* Stage 7 — activity log */
  await clickAt("#log-toggle");
  await sleep(250);
  check("S7: drawer open", await evaljs(sel("#log-drawer") + ".classList.contains('open')"));
  check("S7: 21 audit entries", (await count("#log-list li")) === 21, String(await count("#log-list li")));
  check("S7: rollback entry recorded", (await count("#log-list .log-chip-rollback")) === 1);
  check("S7: confirmed entries recorded", (await count("#log-list .log-chip-confirmed")) === 4);
  await shot("09-activity-log.png");
  await clickAt("#log-close");
  await sleep(250);

  /* Stage 8 — reset */
  await clickAt("#reset-btn");
  await clickAt("#reset-btn");
  await sleep(120);
  await expectText("S8: reset returns to 0 of 10", await textOf("#progress-label"), "0 of 10 steps");
  await expectText("S8: status reset", await textOf("#status-pill"), "Not started");
  await shot("10-after-reset.png");

  check("Final: no console errors during journey", consoleErrs.length === 0, consoleErrs.slice(0, 3).join(" | "));

  const failed = results.filter((r) => !r.pass);
  const lines = results.map((r) => (r.pass ? "- PASS " : "- FAIL ") + r.label + (r.detail && !r.pass ? " — " + r.detail : ""));
  fs.writeFileSync(path.join(SHOTS, "journey-log.md"),
    "# Runbook journey — CDP drive " + new Date().toISOString() + "\n\n" +
    lines.join("\n") + "\n\nConsole errors: " + (consoleErrs.length ? consoleErrs.join(" | ") : "none") + "\n" +
    "\n" + results.length + " checks, " + failed.length + " failures\n");
  console.log("\n" + results.length + " checks, " + failed.length + " failures. Log: screenshots/journey-log.md");

  ws.close();
  chrome.kill();
  process.exit(failed.length ? 1 : 0);
}

main().catch((e) => { console.error("DRIVER ERROR:", e.message); process.exit(2); });

