"use strict";
/* Reproduce: execute S5 -> roll back -> re-open gate. Dump state at each hop. */
const { spawn } = require("child_process");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const CHROME = "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe";
const PORT = 9335;

async function main() {
  const chrome = spawn(CHROME, ["--headless=new", "--disable-gpu", "--remote-debugging-port=" + PORT,
    "--user-data-dir=E:\\codex-prj\\ab-worktrees\\pi-matrix-m5p1\\s4-e1\\.chrome-dbg2", "--no-first-run",
    "--window-size=1440,900", "--hide-scrollbars", "about:blank"], { stdio: "ignore" });
  let targets = [];
  for (let i = 0; i < 60; i++) {
    try { targets = await (await fetch("http://127.0.0.1:" + PORT + "/json/list")).json(); if (targets.some(t => t.type === "page")) break; } catch (_) {}
    await sleep(200);
  }
  const ws = new WebSocket(targets.find(t => t.type === "page").webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let mid = 0; const pending = new Map();
  ws.onmessage = (ev) => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
  const send = (method, params) => new Promise((resolve, reject) => {
    const id = ++mid; pending.set(id, (m) => m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result));
    ws.send(JSON.stringify({ id, method, params: params || {} }));
  });
  const ev = async (expr) => (await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true })).result?.value;
  const click = async (s) => {
    const c = await ev(`(() => { const el = document.querySelector(${JSON.stringify(s)}); if (!el) return null; el.scrollIntoView({block:'center'}); const r = el.getBoundingClientRect(); return { x: Math.round(r.left + r.width/2), y: Math.round(r.top + r.height/2) }; })()`);
    if (!c) { console.log("MISS", s); return false; }
    await send("Input.dispatchMouseEvent", { type: "mousePressed", x: c.x, y: c.y, button: "left", clickCount: 1 });
    await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: c.x, y: c.y, button: "left", clickCount: 1 });
    await sleep(120);
    return true;
  };
  const dump = async (tag) => {
    console.log(tag, JSON.stringify({
      scrimHidden: await ev("document.getElementById('gate-scrim').hidden"),
      gateRendered: await ev("!!document.querySelector('#gate .gate-eyebrow')"),
      phraseInput: await ev("!!document.querySelector('#gate-phrase-input')"),
      openGateBtn: await ev("!!document.querySelector(\"button[data-action='open-gate'][data-step='S5']\")"),
      s5done: await ev("document.querySelector(\".step[data-step-id='S5']\").classList.contains('is-done')"),
      s5rolled: await ev("document.querySelector(\".step[data-step-id='S5'] .badge-rolled\") !== null"),
      progress: await ev("document.getElementById('progress-label').textContent"),
      active: await ev("document.activeElement ? document.activeElement.tagName + '#' + (document.activeElement.id||'') : 'none'")
    }));
  };

  await send("Page.enable"); await send("Runtime.enable");
  await send("Emulation.setDeviceMetricsOverride", { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
  await send("Page.navigate", { url: "file:///E:/codex-prj/ab-worktrees/pi-matrix-m5p1/s4-e1/index.html" });
  await sleep(1000);

  for (const [sid, n] of [["S1", 2], ["S2", 2]]) {
    for (let i = 0; i < n; i++) await click(`input[data-check='${sid}:${i}']`);
    await click(`button[data-action='complete'][data-step='${sid}']`);
  }
  await click("button[data-action='complete'][data-step='S3']");
  await click("button[data-action='complete'][data-step='S4']");
  console.log("progress after S1-4:", await ev("document.getElementById('progress-label').textContent"));

  await click("button[data-action='open-gate'][data-step='S5']"); await dump("after open-gate #1:");
  await click("input[data-gate-check='0']"); await click("input[data-gate-check='1']");
  await ev("(() => { const el = document.querySelector('#gate-phrase-input'); el.focus(); el.value='ledger v2'; el.dispatchEvent(new Event('input',{bubbles:true})); })()");
  await click("#gate [data-action='gate-execute']"); await dump("after execute #1:");

  await click("button[data-action='rollback'][data-step='S5']"); await dump("after rollback arm:");
  await click("button[data-action='rollback'][data-step='S5']"); await dump("after rollback confirm:");

  const ok = await click("button[data-action='open-gate'][data-step='S5']"); console.log("open-gate click:", ok);
  await dump("after open-gate #2:");
  ws.close(); chrome.kill(); process.exit(0);
}
main().catch(e => { console.error("ERR", e.message); process.exit(2); });

