.rb-card .rb-meta { display: flex; gap: 16px; font-size: 13px; color: var(--warn-ink); font-weight: 600; }

.gate-checks { margin: 0 0 16px; }
.gate-phrase label { display: block; font-size: 14px; font-weight: 600; margin-bottom: 8px; }
.gate-phrase label code {
  font-family: var(--mono); background: var(--surface-2); border: 1px solid var(--line);
