/* ===== Tokens ===== */
:root {
  --bg: #f5f6f9;
  --surface: #ffffff;
  --surface-2: #fafbfd;
  --ink: #1a212b;
  --ink-2: #4d5766;
  --ink-3: #66707f;
  --line: #dfe4ec;
  --line-soft: #e9edf3;

  --accent: #4338ca;
  --accent-ink: #3730a3;
  --accent-soft: #eef2ff;
  --accent-line: #c7d2fe;

  --danger: #b42318;
  --danger-ink: #912018;
  --danger-soft: #fef3f2;
  --danger-line: #f4c7c3;

  --warn-bg: #fffaeb;
  --warn-line: #fedf89;
  --warn-ink: #93540a;

  --ok: #067647;
  --ok-soft: #ecfdf3;
  --ok-line: #abefc6;

  --radius: 14px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(16, 24, 32, .05), 0 4px 16px rgba(16, 24, 32, .06);
  --shadow-deep: 0 8px 40px rgba(16, 24, 32, .22);
  --font: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: "Cascadia Code", Consolas, "SF Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
/* The hidden attribute must always win over component display values
   (e.g. .scrim { display:flex } would otherwise stay interactive while "hidden"). */
[hidden] { display: none !important; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.app { max-width: 940px; margin: 0 auto; padding: 44px 36px 80px; }

/* ===== Header ===== */
.runbook-header {
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 32px; padding-bottom: 28px; border-bottom: 1px solid var(--line);
}
.rh-eyebrow {
  margin: 0 0 6px; font-size: 12.5px; font-weight: 700; letter-spacing: .12em;
  text-transform: uppercase; color: var(--accent-ink);
}
.rh-title { margin: 0 0 10px; font-size: 30px; line-height: 1.2; letter-spacing: -.01em; }
.rh-meta { margin: 0; color: var(--ink-2); font-size: 14.5px; }
.rh-meta span { display: inline-block; margin-right: 18px; }

.rh-right { flex: 0 0 auto; width: 264px; display: flex; flex-direction: column; gap: 10px; margin-top: 4px; }
.rh-status-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.status-pill {
  font-size: 12.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  padding: 5px 12px; border-radius: 999px; border: 1px solid var(--line); background: var(--surface); color: var(--ink-2);
  white-space: nowrap;
}
.status-pill[data-state="in-progress"] { background: var(--accent-soft); border-color: var(--accent-line); color: var(--accent-ink); }
.status-pill[data-state="complete"] { background: var(--ok-soft); border-color: var(--ok-line); color: var(--ok); }
.progress-label { font-size: 13.5px; color: var(--ink-2); font-variant-numeric: tabular-nums; }

.meter { height: 8px; border-radius: 999px; background: var(--line-soft); overflow: hidden; }
.meter-fill {
  height: 100%; width: 0%; border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), #6d64e8);
  transition: width .35s ease;
}
.rh-actions { display: flex; gap: 8px; justify-content: flex-end; }

/* ===== Buttons ===== */
.btn {
  font: inherit; font-size: 14.5px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 16px; border-radius: var(--radius-s);
  border: 1px solid var(--line); background: var(--surface); color: var(--ink);
  cursor: pointer; transition: background .15s ease, border-color .15s ease, box-shadow .15s ease;
}
.btn:hover:not(:disabled) { background: var(--surface-2); border-color: #cdd4df; }
.btn-primary { background: #3730a3; border-color: #3730a3; color: #fff; }
.btn-primary:hover:not(:disabled) { background: #312a94; border-color: #312a94; }
.btn-danger { background: var(--danger); border-color: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { background: var(--danger-ink); border-color: var(--danger-ink); }
.btn-danger-ghost { background: transparent; border-color: var(--danger-line); color: var(--danger); }
.btn-danger-ghost:hover:not(:disabled) { background: var(--danger-soft); }
.btn-ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn-ghost:hover:not(:disabled) { background: rgba(16, 24, 32, .06); border-color: transparent; }
.btn-small { font-size: 13px; padding: 6px 11px; }
.btn-large { font-size: 15.5px; padding: 11px 22px; }
/* Disabled: solid, no opacity (keeps text contrast measurable and AA-safe). */
.btn:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; cursor: not-allowed; }
.btn-primary:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }
.btn-danger:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }
.btn-danger-ghost:disabled { background: #eef0f4; border-color: #d5dae2; color: #5c6570; }

.ic { width: 16px; height: 16px; flex: 0 0 auto; }

/* ===== Completion banner ===== */
.completion {
  margin-top: 32px; padding: 28px 32px;
  background: linear-gradient(135deg, var(--ok-soft), #f2fbf6 60%, var(--accent-soft));
  border: 1px solid var(--ok-line); border-radius: var(--radius); box-shadow: var(--shadow);
}
.completion h2 { margin: 0 0 6px; font-size: 22px; display: flex; align-items: center; gap: 12px; }
.completion h2 svg { width: 28px; height: 28px; color: var(--ok); }
.completion .c-sub { margin: 0 0 20px; color: var(--ink-2); }
.c-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 20px; }
.c-stat {
  background: rgba(255,255,255,.75); border: 1px solid var(--line-soft);
  border-radius: var(--radius-s); padding: 12px 16px;
}
.c-stat b { display: block; font-size: 22px; font-variant-numeric: tabular-nums; }
.c-stat span { font-size: 12.5px; color: var(--ink-2); letter-spacing: .02em; text-transform: uppercase; font-weight: 600; }
.c-phases { margin: 0; padding: 0; list-style: none; border-top: 1px dashed var(--line); padding-top: 16px; }
.c-phases li { margin: 6px 0; font-size: 14px; color: var(--ink-2); }
.c-phases b { color: var(--ink); }

/* ===== Ladder ===== */
.ladder { margin-top: 8px; }
.phase { margin-top: 40px; }
.phase-head { display: flex; align-items: baseline; gap: 14px; margin-bottom: 8px; }
.phase-num {
  flex: 0 0 auto; width: 34px; height: 34px; border-radius: 999px;
  background: var(--ink); color: #fff; font-weight: 700; font-size: 15px;
  display: inline-flex; align-items: center; justify-content: center; align-self: center;
}
.phase.is-complete .phase-num { background: var(--ok); }
.phase-title { margin: 0; font-size: 20px; }
.phase-goal { margin: 0 0 18px 48px; color: var(--ink-3); font-size: 14.5px; }
.phase-count { margin-left: auto; font-size: 13px; color: var(--ink-3); font-variant-numeric: tabular-nums; white-space: nowrap; align-self: center; }

/* ===== Step ===== */
.step {
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--surface); margin-bottom: 12px; box-shadow: var(--shadow);
  transition: border-color .2s ease, box-shadow .2s ease, opacity .2s ease;
}
.step.is-locked { background: var(--surface-2); }
.step.is-locked .step-title { color: var(--ink-2); }
.step.is-locked .step-summary { color: var(--ink-3); }
.step.is-current { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft), var(--shadow); }
.step.is-done:not(.is-current) { border-color: var(--ok-line); }
.step.is-done .step-marker { color: var(--ok); }

.step-row {
  width: 100%; display: flex; align-items: center; gap: 14px; text-align: left;
  background: none; border: 0; padding: 16px 20px; cursor: pointer; font: inherit; color: inherit;
  border-radius: var(--radius);
}
.step-row:hover { background: var(--surface-2); }
.step.is-locked .step-row { cursor: default; }
.step.is-locked .step-row:hover { background: none; }

.step-marker {
  flex: 0 0 auto; width: 30px; height: 30px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  border: 2px solid var(--line); color: var(--ink-3); background: var(--surface);
}
.step.is-current .step-marker { border-color: var(--accent); color: var(--accent); }
.step-marker svg { width: 16px; height: 16px; }

.step-main { flex: 1 1 auto; min-width: 0; }
.step-title-line { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.step-title { font-weight: 650; font-size: 16px; }
.step.is-locked .step-title { color: var(--ink-2); font-weight: 550; }
.step-summary { margin: 2px 0 0; font-size: 13.5px; color: var(--ink-3); }

.step-side { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
.badge {
  font-size: 12px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  padding: 3px 9px; border-radius: 999px; white-space: nowrap;
}
.badge-irrev { background: var(--warn-bg); color: var(--warn-ink); border: 1px solid var(--warn-line); }
.badge-check { background: var(--surface-2); color: var(--ink-3); border: 1px solid var(--line); }
.badge-done { background: var(--ok-soft); color: var(--ok); border: 1px solid var(--ok-line); }
.badge-rolled { background: var(--danger-soft); color: var(--danger); border: 1px solid var(--danger-line); }
.badge-upnext { background: var(--accent-soft); color: var(--accent-ink); border: 1px solid var(--accent-line); }
.step-chev { color: var(--ink-3); transition: transform .2s ease; }
.step.is-open .step-chev { transform: rotate(180deg); }

/* Step body */
.step-body { padding: 2px 20px 20px 64px; }
.step-detail { margin: 0 0 14px; padding: 0; list-style: none; }
.step-detail li { position: relative; padding-left: 20px; margin: 7px 0; font-size: 14.5px; color: var(--ink-2); }
.step-detail li::before {
  content: ""; position: absolute; left: 2px; top: .62em;
  width: 7px; height: 7px; border-radius: 2px; background: var(--accent-line);
}
.step-detail code {
  font-family: var(--mono); font-size: 12.5px; background: var(--surface-2);
  border: 1px solid var(--line-soft); border-radius: 5px; padding: 1px 5px;
}

.step-meta { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-bottom: 16px; font-size: 13px; color: var(--ink-3); }
.step-meta b { color: var(--ink-2); font-weight: 600; }

.checks { margin: 0 0 16px; padding: 14px 16px; background: var(--surface-2); border: 1px solid var(--line-soft); border-radius: var(--radius-s); }
.checks-title { margin: 0 0 8px; font-size: 13px; font-weight: 700; color: var(--ink-2); text-transform: uppercase; letter-spacing: .07em; }
.check { display: flex; gap: 10px; align-items: flex-start; margin: 6px 0; font-size: 14.5px; cursor: pointer; }
.check input { width: 24px; height: 24px; margin: 0; flex: 0 0 auto; accent-color: #3730a3; cursor: pointer; }
.check input:disabled { cursor: not-allowed; }

.step-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.step-hint { font-size: 13px; color: var(--ink-3); }
.step-hint.is-error { color: var(--danger); font-weight: 600; }
.step-outcome {
  margin: 0 0 14px; padding: 10px 14px; border-radius: var(--radius-s);
  background: var(--ok-soft); border: 1px solid var(--ok-line);
  color: var(--ok); font-size: 14px; font-weight: 600;
}
.rb-note {
  margin: 12px 0 0; font-size: 13px; color: var(--ink-3);
  padding: 10px 14px; background: var(--surface-2); border: 1px dashed var(--line); border-radius: var(--radius-s);
}

/* ===== Footer ===== */
