.log-list { flex: 1 1 auto; overflow-y: auto; margin: 0; padding: 0; list-style: none; }
.log-list li { display: flex; gap: 10px; padding: 10px 2px; border-bottom: 1px solid var(--line-soft); font-size: 13.5px; align-items: baseline; }
.log-time { flex: 0 0 auto; font-variant-numeric: tabular-nums; color: var(--ink-3); font-size: 12px; }
.log-chip {
  flex: 0 0 auto; font-size: 10.5px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  padding: 2px 8px; border-radius: 999px; border: 1px solid var(--line); color: var(--ink-3); background: var(--surface-2);
}
.log-chip-executed { background: var(--accent-soft); color: var(--accent-ink); border-color: var(--accent-line); }
.log-chip-confirmed { background: #f5f0ff; color: #6941c6; border-color: #d6bbfb; }
.log-chip-rollback { background: var(--warn-bg); color: var(--warn-ink); border-color: var(--warn-line); }
.log-chip-reset { background: var(--danger-soft); color: var(--danger); border-color: var(--danger-line); }
.log-text { color: var(--ink-2); }
.log-empty { color: var(--ink-3); font-size: 14px; }

/* ===== Toast ===== */
#toast {
  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%);
  background: var(--ink); color: #fff; padding: 11px 20px; border-radius: 10px;
  font-size: 14px; box-shadow: var(--shadow-deep); z-index: 80;
}

@media (max-width: 860px) {
  .app { padding: 28px 18px 60px; }
  .runbook-header { flex-direction: column; gap: 18px; }
  .rh-right { width: 100%; }
  .c-stats { grid-template-columns: repeat(2, 1fr); }
  .step-body { padding-left: 20px; }
}
